#nullable enable // autogenerated

using System;
using System.Collections.Generic;

namespace MVZ2.Supporters
{
    [Serializable]
    class SponsorInfos
    {
        public SponsorInfos(SponsorManager manager, SponsorItem[] items)
        {
            List<SponsorSaveItem> saveItems = new List<SponsorSaveItem>();
            foreach (var sponsor in items)
            {
                var planSaveItems = new List<SponsorPlanSaveItem>();
                if (sponsor.Plans == null || sponsor.User == null)
                    continue;
                foreach (var plan in sponsor.Plans)
                {
                    if (plan == null)
                        continue;
                    if (manager.TryGetPlanByID(plan.PlanID, out var id))
                    {
                        planSaveItems.Add(new SponsorPlanSaveItem()
                        {
                            rank = id.rank,
                            rankType = id.type,
                        });
                    }
                }
                if (planSaveItems.Count > 0)
                {
                    saveItems.Add(new SponsorSaveItem(sponsor.User.Name ?? string.Empty, planSaveItems.ToArray()));
                }
            }
            sponsors = saveItems.ToArray();
        }
        public long lastUpdateTime;
        public SponsorSaveItem[] sponsors;
    }
    [Serializable]
    class SponsorSaveItem
    {
        public string name;
        public SponsorPlanSaveItem[] plans;

        public SponsorSaveItem(string name, SponsorPlanSaveItem[] plans)
        {
            this.name = name;
            this.plans = plans;
        }
    }
    [Serializable]
    class SponsorPlanSaveItem
    {
        public int rank;
        public int rankType;
    }
}
